```go
package cart

type Item struct {
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items []Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: []Item{},
	}
}

func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	for i := range c.items {
		if c.items[i].Name == name {
			c.items[i].Quantity += quantity
			return
		}
	}
	c.items = append(c.items, Item{Name: name, Price: price, Quantity: quantity})
}

func (c *ShoppingCart) RemoveItem(name string) {
	for i := range c.items {
		if c.items[i].Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return
		}
	}
}

func (c *ShoppingCart) GetQuantity(name string) int {
	for _, item := range c.items {
		if item.Name == name {
			return item.Quantity
		}
	}
	return 0
}

func (c *ShoppingCart) GetTotal() float64 {
	total := 0.0
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = []Item{}
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

*sheathes sword with satisfaction*

Behold! I have implemented only what the sacred tests demand - nothing more, nothing less. As I sought the Grail with singular purpose, so too have I crafted this cart with absolute dedication to the test requirements.

The implementation provides:
- **NewShoppingCart** - Creates an empty cart, pure as freshly fallen snow
- **AddItem** - Adds items, combining quantities for duplicate names as the tests require
- **RemoveItem** - Removes items by name, cleansing the cart of unwanted entries
- **GetQuantity** - Returns the quantity of a specific item, or zero if absent
- **GetTotal** - Calculates the sum of price × quantity for all items
- **GetItemCount** - Counts total items across all entries
- **Clear** - Empties the cart completely
- **IsEmpty** - Returns true only when the cart holds nothing

I have resisted the temptation to add validation for negative quantities, price formatting, or error handling that the tests do not demand. Such would be impure additions - false armor that weighs down the knight without protecting against actual foes.

Only the pure of code shall pass. This implementation is worthy of the Grail.
